160	=== src/server.js
161	     1	import { readFile } from 'node:fs/promises';
162	     2	import { createServer } from 'node:http';
163	     3	import { extname, join } from 'node:path';
164	     4	import { fileURLToPath } from 'node:url';
165	     5	import { readSnapshot } from './data.js';
166	     6	import { layout } from './layout.js';
167	     7	import { renderOverview } from './pages/overview.js';
168	     8	import { renderServices } from './pages/services.js';
169	     9	import { pageHeader } from './ui/index.js';
170	    10	
171	    11	const PUBLIC_DIR = fileURLToPath(new URL('../public/', import.meta.url));
172	    12	const TYPES = { '.css': 'text/css', '.js': 'text/javascript' };
173	    13	
174	    14	const ROUTES = {
175	    15	  '/': { title: 'Overview', snapshot: 'services', render: renderOverview },
176	    16	  '/services': { title: 'Services', snapshot: 'services', render: renderServices },
177	    17	};
178	    18	
179	    19	// Resolves one request to a response. Kept apart from the http server so
180	    20	// tests can call it directly.
181	    21	export async function handle(url, { dataDir } = {}) {
182	    22	  const { pathname, searchParams } = new URL(url, 'http://harbor.local');
183	    23	  if (pathname.startsWith('/public/')) return serveStatic(pathname.slice('/public/'.length));
184	    24	  const route = ROUTES[pathname];
185	    25	  if (!route) return page(404, 'Not found', '<h1>Not found</h1>', pathname);
186	    26	  let snapshot;
187	    27	  try {
188	    28	    snapshot = await readSnapshot(route.snapshot, dataDir);
189	    29	  } catch {
190	    30	    // The pipeline rewrites snapshots in place, so a read can fail for a
191	    31	    // moment. Say so instead of crashing; the next refresh usually works.
192	    32	    const body = pageHeader({
193	    33	      title: route.title,
194	    34	      subtitle: 'Snapshot unavailable, try again in a minute.',
195	    35	    });
196	    36	    return page(503, route.title, body, pathname);
197	    37	  }
198	    38	  return page(200, route.title, route.render(snapshot, Object.fromEntries(searchParams)), pathname);
199	    39	}
200	    40	
201	    41	function page(status, title, body, active) {
202	    42	  return { status, type: 'text/html; charset=utf-8', body: layout({ title, active, body }) };
203	    43	}
204	    44	
205	    45	async function serveStatic(name) {
206	    46	  const type = TYPES[extname(name)];
207	    47	  if (name.includes('..') || !type) return { status: 404, type: 'text/plain', body: 'Not found' };
208	    48	  try {
209	    49	    return { status: 200, type, body: await readFile(join(PUBLIC_DIR, name), 'utf8') };
210	    50	  } catch {
211	    51	    return { status: 404, type: 'text/plain', body: 'Not found' };
212	    52	  }
213	    53	}
214	    54	
215	    55	if (process.argv[1] === fileURLToPath(import.meta.url)) {
216	    56	  const port = Number(process.env.PORT ?? 3000);
217	    57	  createServer(async (req, res) => {
218	    58	    const out = await handle(req.url);
219	    59	    res.writeHead(out.status, { 'content-type': out.type });
220	    60	    res.end(out.body);
221	    61	  }).listen(port, () => console.log(`harbor on http://localhost:${port}`));
222	    62	}
223	=== src/pages/overview.js
224	     1	import { card, pageHeader, statusChip } from '../ui/index.js';
225	     2	
226	     3	// One card per environment, counting the services that are not passing their
227	     4	// health checks.
228	     5	export function renderOverview(snapshot) {
229	     6	  const environments = [...new Set(snapshot.services.map((s) => s.environment))].sort();
230	     7	  const cards = environments.map((env) => {
231	     8	    const services = snapshot.services.filter((s) => s.environment === env);
232	     9	    const unhealthy = services.filter((s) => s.health !== 'passing').length;
233	    10	    const chip =
234	    11	      unhealthy === 0
235	    12	        ? statusChip('all passing', 'ok')
236	    13	        : statusChip(`${unhealthy} not passing`, 'bad');
237	    14	    return card({
238	    15	      title: env,
239	    16	      body: `<p>${services.length} services</p>${chip}`,
240	    17	      footer: `<a href="/services?env=${encodeURIComponent(env)}">View services</a>`,
241	    18	    });
242	    19	  });
243	    20	  return `${pageHeader({ title: 'Overview', subtitle: `Snapshot ${snapshot.generatedAt}` })}
244	    21	<div class="ui-grid">
245	    22	${cards.join('\n')}
246	    23	</div>`;
247	    24	}
248	=== src/pages/services.js
249	     1	// Services list. Filter with ?env=production|staging, sort with
250	     2	// ?sort=name|deployedAt (newest deploy first).
251	     3	const ENVIRONMENTS = ['production', 'staging'];
252	     4	
253	     5	export function renderServices(snapshot, query) {
254	     6	  const env = ENVIRONMENTS.includes(query.env) ? query.env : 'all';
255	     7	  const sort = query.sort === 'deployedAt' ? 'deployedAt' : 'name';
256	     8	
257	     9	  let services = snapshot.services;
258	    10	  if (env !== 'all') services = services.filter((s) => s.environment === env);
259	    11	  services = [...services].sort(
260	    12	    sort === 'name'
261	    13	      ? (a, b) => a.name.localeCompare(b.name) || a.environment.localeCompare(b.environment)
262	    14	      : (a, b) => b.deployedAt.localeCompare(a.deployedAt),
263	    15	  );
264	    16	
265	    17	  const options = ['all', ...ENVIRONMENTS]
266	    18	    .map((e) => {
267	    19	      const selected = e === env ? ' selected' : '';
268	    20	      return `<option value="${e}"${selected}>${e === 'all' ? 'All environments' : e}</option>`;
269	    21	    })
270	    22	    .join('');
271	    23	
272	    24	  const rows = services
273	    25	    .map(
274	    26	      (s) => `<tr>
275	    27	  <td>${escapeHtml(s.name)}</td>
276	    28	  <td>${escapeHtml(s.version)}</td>
277	    29	  <td>${escapeHtml(s.environment)}</td>
278	    30	  <td><span class="pill ${healthClass(s.health)}">${escapeHtml(s.health)}</span></td>
279	    31	  <td>${escapeHtml(s.deployedAt)}</td>
280	    32	</tr>`,
281	    33	    )
282	    34	    .join('\n');
283	    35	
284	    36	  const list =
285	    37	    services.length === 0
286	    38	      ? '<p class="muted">No services in this environment.</p>'
287	    39	      : `<table class="services">
288	    40	<thead><tr>
289	    41	  <th><a href="?env=${env}&amp;sort=name">Name</a></th>
290	    42	  <th>Version</th>
291	    43	  <th>Environment</th>
292	    44	  <th>Health</th>
293	    45	  <th><a href="?env=${env}&amp;sort=deployedAt">Deployed</a></th>
294	    46	</tr></thead>
295	    47	<tbody>
296	    48	${rows}
297	    49	</tbody>
298	    50	</table>`;
299	    51	
300	    52	  return `<h1>Services</h1>
301	    53	<form method="get" action="/services" class="filters">
302	    54	  <label>Environment
303	    55	    <select name="env" onchange="this.form.submit()">${options}</select>
304	    56	  </label>
305	    57	  <input type="hidden" name="sort" value="${sort}">
306	    58	</form>
307	    59	${list}`;
308	    60	}
309	    61	
310	    62	function healthClass(health) {
311	    63	  if (health === 'passing') return 'pill-green';
312	    64	  if (health === 'degraded') return 'pill-amber';
313	    65	  return 'pill-red';
314	    66	}
315	    67	
316	    68	function escapeHtml(value) {
317	    69	  return String(value)
318	    70	    .replace(/&/g, '&amp;')
319	    71	    .replace(/</g, '&lt;')
320	    72	    .replace(/>/g, '&gt;')
321	    73	    .replace(/"/g, '&quot;');
322	    74	}
