379	     3	/**
380	     4	 * A GET form for a page's filters. `fields` is trusted HTML, usually
381	     5	 * `selectField` output; public/harbor.js submits the form when a field marked
382	     6	 * `data-autosubmit` changes. `keep` carries query state the bar should not
383	     7	 * drop, such as the current sort.
384	     8	 *
385	     9	 * @param {object} opts
386	    10	 * @param {string} opts.action
387	    11	 * @param {string[]} opts.fields
388	    12	 * @param {Record<string, string | undefined>} [opts.keep]
389	    13	 * @returns {string}
390	    14	 */
391	    15	export function filterBar({ action, fields, keep = {} }) {
392	    16	  const hidden = Object.entries(keep)
393	    17	    .filter(([, v]) => v !== undefined && v !== '')
